# Coefficients dictionary from previous run
coeffs = {
    0: (1, 0, 0), 1: (0, 1, 0), 2: (0, 0, 1), 3: (10, -1, -1), 4: (-10, 11, 0), 5: (0, -10, 11),
    6: (110, -11, -21), 7: (-210, 131, 10), 8: (100, -220, 121), 9: (1210, -21, -341),
    10: (-3410, 1551, 320), 11: (3200, -3730, 1231), 12: (12310, 1969, -4961), 13: (-49610, 17271, 6930),
    14: (69300, -56540, 10341), 15: (103410, 58959, -66881)
}

indices = list(range(16))
found_s3 = False
print("Checking S=3 solutions (i, j, k) for 0 <= i < j < k <= 15:")

for i in range(16):
    for j in range(i + 1, 16):
        for k in range(j + 1, 16):
            ai, bi, ci = coeffs[i]
            aj, bj, cj = coeffs[j]
            ak, bk, ck = coeffs[k]

            A = ai + aj + ak
            B = bi + bj + bk
            C = ci + cj + ck

            if A == 2025 and B == 0 and C == 0:
                print(f"Found S=3 solution! Indices: ({i}, {j}, {k}). Sum: {A}, B: {B}, C: {C}")
                found_s3 = True
                break
        if found_s3:
            break
    if found_s3:
        break

if not found_s3:
    print("No S=3 solution found for indices up to 15.")
